        {u"Annotation"_ustr, u"Comment on AA...BB"_ustr, 4},
        {u"Annotation"_ustr, u"Comment on AAAAAA"_ustr, 5},
        {u"Text"_ustr, u"AAAAAA"_ustr, 0},
